def get_parsetable_str():
    global g_grammar
    global g_conflicts


    rules = list(e for opts in g_grammar.values() for e in opts)

    COLLECTION: list[set[Item]] = []
    GOTO: dict[int, dict[Terminal|Nonterminal, int]] = {}
    X: set[tuple[int, Nonterminal]] = set()
    

    def CANONICAL(itemset: set[Item]) -> dict:
        """Compute the canonical LR(0) collection."""

        state = len(COLLECTION)
        GOTO[state] = {}
        COLLECTION.append(itemset)
        for token, closure in GOTOS(itemset).items():
            if closure in COLLECTION:
                GOTO[state][token] = COLLECTION.index(closure)
            else:
                GOTO[state][token] = len(COLLECTION)
                CANONICAL(closure)
            if isinstance(token, Nonterminal): X.add((state, token))


    def CLOSURE(kernel: set[Item]) -> set[Item]:
        """Compute the closure of an LR(0) kernel."""

        closure = set()
        expansions = kernel
        while expansions:
            item = expansions.pop()
            if item in closure: continue
            closure.add(item)
            if isinstance(item.current, Nonterminal):
                for production in g_grammar[item.current]:
                    expansions.add(Item(0, production))
        return closure
    

    def GOTOS(itemset: set[Item]) -> dict[Terminal|Nonterminal, set[Item]]:
        """Compute the goto transitions of a given state."""

        gotos: dict[Terminal|Nonterminal, set[Item]] = {}
        for item in itemset:
            if item.isReduction: continue
            if item.current not in gotos: gotos[item.current] = set()
            gotos[item.current].add(Item(item.dot+1, item.production))
        for token, kernel in gotos.items():
            gotos[token] = CLOSURE(kernel)
        return gotos


    def LOOKAHEADS() -> dict[tuple[int, Production], set[Terminal]]:
        """LALR lookahead computation algorithm, adapted from (DeRemer and Penello, 1982).
        Accessible via the ACM Digital Library: https://dl.acm.org/doi/epdf/10.1145/69622.357187.
        
        ### Quantities involved:

        `DR` *dict*
            A function `DR[(p, A)] = {t₀, ..., tₙ}`.
            Given state p, on `Nonterminal` A, return the set of `Terminal`s which could be (directly) read next.
        
        `reads` *dict*
            A relation `reads[(p, A)] = [(q₀, B₁), ..., (qₙ₋₁, Bₙ)]`.
            Given state p, on `Nonterminal` A, return a list of `(int, Nonterminal)` pairs such that
            (p, A) *reads* (q, B) iff p -- A --> q -- B --> and B =>* ε; 
            i.e. all (q, B) such that whatever is read after state q could be read after state p given A.
            
        `Read` *dict*
            A function `Read[(p, A)] = {t₀, ..., tₙ}`.
            Result of `DIGRAPH(reads, DR)`. Consolidates all Direct Read sets found on SCCs of reads.
            Given state p, on `Nonterminal` A, returns the set of `Terminal`s t which could be read
                a) directly, or
                b) after one or more ε-reductions.
        
        `includes` *dict*
            A relation `includes[(p, A)] = [(q₀, B₁), ..., (qₙ₋₁, Bₙ)]`.
            Given state p, on `Nonterminal` A, return a list of `(int, Nonterminal)` pairs such that
            (p, A) *includes* (q, B) iff B -> βAγ, γ =>* ε, and p --* β --> q; 
            i.e. all (q, B) such that whatever is read after B in q can be read after A in p; note
            that this is a subset relation, i.e. Follow(q, B) ≤ Follow(p, A) (see Follow).

        `lookback` *dict*
            A relation `lookback[(p, A -> ω)] = [(q₀, B₀), ..., (qₙ, Bₙ)]`
            Given state p, on production A -> ω, return a list of `(int, Nonterminal)` pairs such that
            (p, A -> ω) p --* ω --> q; i.e. all (q, B) such that ω accesses q from p.
        
        `Follow` *dict*
            A function `Follow[(p, A)] = {t₀, ..., tₙ}`.
            Result of `DIGRAPH(includes, Read)`. Consolidates all Read sets found on SCCs of includes.
            Given state p, on `Nonterminal` A, return the set of `Terminal`s which could be read after A.
            
        :returns LA: 
            A function `LA[(p, A -> ω)] = {t₀, ..., tₙ}`.
            Union of all `Follow[(q, A)]` such that (p, A -> ω) *lookback* (q, A);
            i.e. the set of all `Terminal`s which could be read after reducing ω in state p to A in state q.
        """
        
        def accesses(p: int, sequence: list[Terminal|Nonterminal]) -> int|None:
            """Applies a sequence of transitions from state p, returning the resultant state or `None`."""
            for t in sequence:
                try: p = GOTO[p][t]
                except: return None
            return p
        
        nonlocal X
        DR: dict[tuple[int, Nonterminal], set[Terminal]] = { transition : set() for transition in X }
        reads: dict[tuple[int, Nonterminal], list[tuple[int, Nonterminal]]] = { transition : [] for transition in X }
        includes: dict[tuple[int, Nonterminal], list[tuple[int, Nonterminal]]] = { transition : [] for transition in X }
        lookback: dict[tuple[int, Production], list[tuple[int, Nonterminal]]] = {}
        
        for (p, A) in X:
            q = GOTO[p][A]
            for B in GOTO[q]:
                # direct read
                if isinstance(B, Terminal):
                    DR[(p, A)].add(B)
                # reads relation
                elif isinstance(B, Nonterminal) and NULLABLE(B):
                    reads[(p, A)].append((q, B))

            for production in g_grammar[A]:
                # includes relation
                nullable = True
                # enumerating backwards allows us to stop iteration at the first nonnullable token
                for i, B in enumerate(reversed(production.pattern)):
                    if isinstance(B, Nonterminal):
                        q = accesses(p, production.pattern[:-(i+1)])
                        if q is not None: includes[(q, B)].append((p, A))
                        if nullable: break
                        nullable = NULLABLE(B)
                    else: break
                # lookback relation
                q = accesses(p, production.pattern)
                if q is not None:
                    if not (q, production) in lookback: lookback[(q, production)] = []
                    lookback[(q, production)].append((p, A))

        Read = DIGRAPH(reads, DR)
        Follow = DIGRAPH(includes, Read)

        LA = { (q, production) : set() for (q, production) in lookback.keys() }
        for (q, production) in lookback:
            for (p, A) in lookback[(q, production)]:
                LA[(q, production)].update(Follow[(p, A)])

        return LA


    def DIGRAPH(
            R: dict[tuple[int, Nonterminal], list[tuple[int, Nonterminal]]], 
            f: dict[tuple[int, Nonterminal], set[Terminal]]
        ) -> dict[tuple[int, Nonterminal], set[Terminal]]:
        """The DeRemer-Penello Digraph algorithm.
        
        :param relation R: A relation on X.
        :param function f: A set-valued function.
        :returns F (function): A function from X to sets."""

        F: dict[tuple[int, Nonterminal], set[Terminal]] = {}
        S: list[tuple[int, Nonterminal]] = []
        N: dict[tuple[int, Nonterminal], int] = dict.fromkeys(X, 0)
        
        def TRAVERSE(x):
            S.append(x)
            d = len(S)
            N[x] = d
            F[x] = f[x]
            for y in R[x]:
                if N[y] == 0: TRAVERSE(y)
                N[x] = min(N[x], N[y])
                F[x].update(F[y])
            if N[x] == d:
                while S.pop() != x:
                    N[S[-1]] = float('inf')
                    if x != S[-1]: F[S[-1]] = F[x]
    
        for x in X:
            if N[x] == 0:
                TRAVERSE(x)

        return F


    def NULLABLE(rule: Terminal|Nonterminal) -> bool:
        return (
            isinstance(rule, Nonterminal)
            and any(
                (production.pattern == [])
                or all(NULLABLE(token) for token in production.pattern if not token == rule)
                for production in g_grammar[rule]
            )
        )
    

    CANONICAL(CLOSURE({ Item(0, g_grammar[START()][0]) }))

    
    LA: dict[tuple[int, Production], set[Terminal]] = LOOKAHEADS()
    TABLE = { p : {} for p in range(len(COLLECTION)) }
    conflicts = {}
    
    for p, itemset in enumerate(COLLECTION):
        print(f"State {p}")
        for item in itemset:
            if (p, item.production) in LA:
                print(f"    {item}, {LA[(p, item.production)]}")
            else:
                print(f"    {item}, S")
    
    
    for p, itemset in enumerate(COLLECTION):
        for item in itemset:
            A = item.production
            lookaheads = LA.get((p, A))
            if item.isReduction and lookaheads is not None:
                for t in lookaheads:
                    TABLE[p][t] = TABLE[p].get(t, set()).union({("R", rules.index(A))})
            else:
                t = item.current
                q = GOTO[p].get(t)
                if t is None:
                    action = ("A", True)
                else:
                    action = ("S" if isinstance(t, Terminal) else "G", q)
                TABLE[p][t] = TABLE[p].get(t, set()).union({ action })

        for A, actions in TABLE[p].items():
            TABLE[p][A] = list(sorted(actions, key=lambda tup: tup[0] == "R"))
            
            if len(actions) > 1:

                if not p in conflicts:
                    conflicts[p] = {}

                conflict = "/".join(action[0] for action in TABLE[p][A])

                if not conflict in conflicts:
                    conflicts[p][conflict] = []
                
                conflicts[p][conflict].append(A)
        
        if conflicts: 
            g_conflicts = f"Found {len(conflicts)} conflicts."
            for p, conflictTypes in conflicts.items():
                for label, tokens in conflictTypes.items():
                    g_conflicts += f"\n(state {p}) {label} conflict on token{"s"*(len(tokens) != 1)} {", ".join(token.__repr__() for token in tokens)}"
        else:
            g_conflicts = "No conflicts found."
    
    print(g_conflicts)
    
    grammar = f"""-------{{ GRAMMAR }}-------
{"\n".join(f"Rule {i:<3} {str(rule)}" for i, rule in enumerate(rules))}"""

    if CONFIG.flags.debug: 
        print(grammar)
        print()

        categories = [*sorted(g_terminals, key=str), EOI(), *g_grammar.keys()]
        categories.remove(START())
        parsetable = displayTable(
            title="LALR Table",
            columns=dict.fromkeys(("State", *map(str, categories)), {}),
            rows=[(str(state), *(lstToStr(edges.get(token, [("",)])[0]) for token in categories)) for state, edges in TABLE.items()]
            )
        
        print("------{ AUTOMATON }------")
        for p, closure in enumerate(COLLECTION):
            print(f"State {p}")
            for item in closure:
                print(f"    {item}")
            print()

        print(parsetable)


    return f"""
##### PARSETABLE #####



# {str(grammar).replace("\n", "\n# ")}



# Parsetable constructed with {len(TABLE)} state{"s"*(len(TABLE)!=1)}.
# {g_conflicts.replace("\n", "\n# ")}



indentation = {g_indentation}
newlines = {g_newlines}



rules = (
    {",\n    ".join(rule.__repr__() for rule in rules)}
)



table = {{
    {",\n    ".join(f"""{state} : {{
        {",\n        ".join(f"{token.__repr__()} : {actions}" for token, actions in transitions.items())}
    }}""" for state, transitions in TABLE.items())}
}}"""


def embed_eval(filename: str, modulename: str) -> str:
    from re import Match
    from re import sub

    def replace_fname(match: Match) -> str:
        return f"p_{modulename}_{match.group().removeprefix("p_")}"

    with open(filename) as file:
        return sub(
            pattern=r"p_\w*\(",
            repl=replace_fname,
            string=file.read()
        )



##### evaluation #####



class __Expr__(__Sequence__):
    """Immutable, callable `Sequence` object which returns its elements as instances of itself."""

    SEMANTICS = { fname : func for fname, func in globals().items() if fname.startswith("p_")}

    def __new__(cls, node):
        return (
            super().__new__(cls) if isinstance(node, __Rule__)
            else node.tok if isinstance(node, __Token__)
            else node
        )
        
    def __init__(self, node: __Rule__):
        self._children = node.children
        self._node = node

    def __getitem__(self, index: int|slice):
        item = self._children[index]
        if isinstance(index, slice):
            return tuple(__Expr__(e) for e in item)
        return __Expr__(item)
  
    def __len__(self):
        return len(self._children)
   
    def __str__(self):
        return self._node.__str__()

    def __repr__(self):
        return self._node.__repr__()

    def __call__(self, i: int = None, *args, **kwargs):
        e = self if (i == None) else self[i]
        return self.evaluate(e, *args, **kwargs)

    def default(self, x: '__Expr__'):
        return x(0)

    def get_function(self, node: __Rule__):
        return (
            __Expr__.SEMANTICS.get(f"{node.fname}_{node.variant}")
            or __Expr__.SEMANTICS.get(node.fname)
            or self.default
        )

    def evaluate(self, expr, *args, **kwargs):
        return (
            self.get_function(expr._node)(expr, *args, **kwargs) if isinstance(expr, __Expr__)
            else expr
        )
